  document.body.append(modal);modal.querySelector('.wl-close').addEventListener('click',()=>close());modal.querySelector('#worldLifeExit').addEventListener('click',()=>close());modal.querySelector('#worldLifeAction').addEventListener('click',()=>activate());modal.addEventListener('cancel',e=>{e.preventDefault();close();});
