 function makeChoices(labels){node('worldLifeChoices').replaceChildren(...labels.map((label,i)=>{const button=document.createElement('button');button.type='button';button.className='wl-choice';button.textContent=label;button.dataset.choice=String(i);button.addEventListener('click',()=>choice(i));return button;}));}
